-- PostgreSQL 17 / 현재 Docker 개발 DB 전용. 실행 방법과 계정은 같은 폴더 README.md 참고.
-- 같은 시드는 재실행해도 추가되지 않는다. 기존 시드 상품의 예전 공통 설명은 갱신한다.
BEGIN;
SET LOCAL TIME ZONE 'Asia/Seoul';
SET LOCAL search_path = pg_temp, public;
SET LOCAL lock_timeout = '10s';
SELECT pg_advisory_xact_lock(20261119, 1);

DO $guard$
BEGIN
    IF current_setting('oishidam.seed_environment', true) IS DISTINCT FROM 'development'
       OR current_database() NOT IN ('oishidam', 'oishidam_seed_verify') THEN
        RAISE EXCEPTION '개발 DB에서만 실행: SET oishidam.seed_environment = development';
    END IF;
END $guard$;

